//! A Channel's reads against C's (channel.c `Read`, `ReadClassData`,
//! `GetNextData` and `ClearValues`): one Object per read, the next starting
//! where the last stopped; with Skip set anything before a `Begin` ignored,
//! and without it an error; the errors for input that ends inside an
//! Object, an unknown class and a misplaced `IsA`; and the warnings for
//! items no class reads, which Strict makes errors, after which the next
//! read starts where C's would.
//!
//! `channel_read_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/channel_read_probe.c`.

use crate::common::native_dump;
#[rustfmt::skip]
#[path = "channel_read_oracle/cases.rs"]
mod cases;

use ast_core::{Channel, NativeChannel, StringSource};

/// A Channel made as the probe makes it, with `options` (any of `Skip=1`,
/// `Strict=1` and `ReportLevel=0`), reading `lines`.
fn channel(options: &str, lines: &[&str]) -> NativeChannel {
    let mut ch = NativeChannel::new();
    ch.set_source(Box::new(StringSource::new(&lines.join("\n"))));
    for option in options.split(',').map(str::trim).filter(|o| !o.is_empty()) {
        match option {
            "Skip=1" => ch.config_mut().set_skip(true),
            "Strict=1" => ch.config_mut().set_strict(true),
            "ReportLevel=0" => ch.config_mut().set_report_level(0),
            other => panic!("no option {other}"),
        }
    }
    ch
}

/// Cases the port does not yet match, with the reason; the companion test
/// fails once one matches. C's loaders read their numbers with
/// `astReadDouble` and `astReadInt`, which report AST__BADIN for a string
/// value, and C has then read only up to that class's part of the Object,
/// so its next read starts there; the port takes the string without error
/// and reads the whole Object before loading it.
const EXCLUDED: &[(&str, &str)] = &[
    (
        "string_for_double",
        "a string read as a number is not an error",
    ),
    (
        "string_for_int",
        "a string read as a number is not an error",
    ),
];

/// The reads of a case, as the port makes them, each as the probe prints it.
fn port_reads(options: &str, lines: &[&str], n: usize) -> Vec<(String, i32, Vec<String>)> {
    let mut ch = channel(options, lines);
    (0..n)
        .map(|_| {
            let (class, status) = match ch.read() {
                Ok(Some(obj)) => {
                    let text = native_dump(&obj).unwrap();
                    let first = text.lines().next().unwrap_or("");
                    (first.split_whitespace().nth(1).unwrap_or("").to_string(), 0)
                }
                Ok(None) => (String::new(), 0),
                Err(e) => (String::new(), e.code() as i32),
            };
            (class, status, ch.warning_texts().to_vec())
        })
        .collect()
}

#[test]
fn excluded_cases_still_differ() {
    for &(name, reason) in EXCLUDED {
        let &(_, options, lines, reads) = cases::CASES
            .iter()
            .find(|(n, ..)| *n == name)
            .unwrap_or_else(|| panic!("no case {name}"));
        let want: Vec<(String, i32, Vec<String>)> = reads
            .iter()
            .map(|&(c, s, w)| (c.to_string(), s, w.iter().map(|x| x.to_string()).collect()))
            .collect();
        assert_ne!(
            port_reads(options, lines, reads.len()),
            want,
            "{name} now matches C; remove it from EXCLUDED ({reason})"
        );
    }
}

#[test]
fn reads_match_c() {
    let mut failed = Vec::new();
    for &(name, options, lines, reads) in cases::CASES {
        if EXCLUDED.iter().any(|(e, _)| *e == name) {
            continue;
        }
        let mut ch = channel(options, lines);
        for (i, &(class, status, warnings)) in reads.iter().enumerate() {
            let (got_class, got_status) = match ch.read() {
                Ok(Some(obj)) => {
                    let text = native_dump(&obj).unwrap();
                    let first = text.lines().next().unwrap_or("");
                    let class = first.split_whitespace().nth(1).unwrap_or("").to_string();
                    (class, 0)
                }
                Ok(None) => (String::new(), 0),
                Err(e) => (String::new(), e.code() as i32),
            };
            let got_warnings: Vec<&str> = ch.warning_texts().iter().map(String::as_str).collect();
            if got_class != class || got_status != status || got_warnings != warnings {
                failed.push(format!(
                    "{name} read {}: got ({got_class:?}, {got_status}, {got_warnings:?}), \
                     C ({class:?}, {status}, {warnings:?})",
                    i + 1
                ));
            }
        }
    }
    assert!(failed.is_empty(), "{}", failed.join("\n"));
}
